/* im-bridge 面板样式（im- 前缀防泄漏；[data-plugin-scope] 作用域注入）
   色值一律取宿主主题变量（对齐 browser-desk/terminal-desk 教训）：
   - 背景：--c-bg-base / --c-bg-elevated / --c-bg-surface / --c-bg-hover / --c-bg-active
   - 文字：--c-text-primary / --c-text-secondary / --c-text-tertiary / --c-text-muted
   - 状态：--c-status-danger/success/warning/info；--c-primary
   - 边框：--c-border 必须带 alpha（/0.08~0.2） */

.im-root {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  min-width: 0;
  background: rgb(var(--c-bg-base));
  color: rgb(var(--c-text-primary));
  font-size: 13px;
  line-height: 1.45;
}

/* ── 头部 Tab（36px）────────────────────────────────────────── */
.im-header {
  height: 36px;
  flex: none;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 8px;
  background: rgb(var(--c-bg-elevated));
  border-bottom: 1px solid rgb(var(--c-border) / 0.08);
}
.im-tab {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 26px;
  padding: 0 10px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: rgb(var(--c-text-secondary));
  font-size: 12px;
  cursor: pointer;
}
.im-tab:hover { background: rgb(var(--c-bg-hover)); color: rgb(var(--c-text-primary)); }
.im-tab.on { background: rgb(var(--c-bg-active)); color: rgb(var(--c-primary)); }
.im-spacer { flex: 1; }
.im-action {
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: rgb(var(--c-text-secondary));
  font-size: 11px;
  padding: 2px 7px;
  cursor: pointer;
  white-space: nowrap;
}
.im-action:hover:not(:disabled) { background: rgb(var(--c-bg-hover)); color: rgb(var(--c-text-primary)); }
.im-action:disabled { opacity: 0.4; cursor: default; }
.im-action.danger:hover:not(:disabled) { color: rgb(var(--c-status-danger)); }

/* 状态点 */
.dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: rgb(var(--c-text-muted) / 0.5); }
.dot-ready { background: rgb(var(--c-status-success)); }
.dot-starting { background: rgb(var(--c-status-warning)); }
.dot-stopped { background: rgb(var(--c-status-danger)); }

/* ── 主体 ───────────────────────────────────────────────────── */
.im-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  scrollbar-width: thin;
}
.im-error {
  flex: none;
  margin: 8px 8px 0;
  padding: 8px 10px;
  border: 1px solid rgb(var(--c-status-danger) / 0.35);
  border-radius: 7px;
  background: rgb(var(--c-bg-surface));
  color: rgb(var(--c-status-danger));
  font-size: 12px;
}
.im-card {
  border: 1px solid rgb(var(--c-border) / 0.1);
  border-radius: 8px;
  background: rgb(var(--c-bg-surface));
  padding: 8px 10px;
}
.im-card-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  color: rgb(var(--c-text-primary));
  margin-bottom: 6px;
}
.im-kv {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 2px 10px;
  font-size: 12px;
  color: rgb(var(--c-text-tertiary));
  margin-bottom: 8px;
}
.im-kv b { font-weight: 500; color: rgb(var(--c-text-primary)); text-align: right; }
.im-err-text { color: rgb(var(--c-status-danger)); }
.im-row { display: flex; align-items: center; gap: 6px; }
.im-btn {
  height: 24px;
  padding: 0 10px;
  border: 1px solid rgb(var(--c-border) / 0.14);
  border-radius: 6px;
  background: rgb(var(--c-bg-base));
  color: rgb(var(--c-text-secondary));
  font-size: 12px;
  cursor: pointer;
}
.im-btn:hover:not(:disabled) { border-color: rgb(var(--c-primary)); color: rgb(var(--c-primary)); }
.im-btn:disabled { opacity: 0.4; cursor: default; }
.im-btn.primary {
  background: rgb(var(--c-primary) / 0.14);
  border-color: rgb(var(--c-primary) / 0.4);
  color: rgb(var(--c-primary));
}
.im-empty {
  padding: 14px 0;
  text-align: center;
  color: rgb(var(--c-text-muted));
  font-size: 12px;
}
.im-inst {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 4px;
  border-radius: 6px;
  font-size: 12px;
}
.im-inst:hover { background: rgb(var(--c-bg-hover) / 0.6); }
.im-inst-name { color: rgb(var(--c-text-primary)); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.im-inst-meta { color: rgb(var(--c-text-tertiary)); font-size: 11px; white-space: nowrap; }

/* ── 编辑弹层 ───────────────────────────────────────────────── */
.im-mask {
  position: absolute;
  inset: 0;
  background: rgb(0 0 0 / 0.4);
  display: grid;
  place-items: center;
  z-index: 10;
}
.im-modal {
  width: min(420px, calc(100% - 24px));
  max-height: calc(100% - 24px);
  overflow-y: auto;
  background: rgb(var(--c-bg-elevated));
  border: 1px solid rgb(var(--c-border) / 0.14);
  border-radius: 10px;
  padding: 12px;
  box-shadow: 0 8px 28px rgb(0 0 0 / 0.25);
}
.im-form { display: flex; flex-direction: column; gap: 8px; margin: 8px 0 10px; }
.im-field { display: grid; grid-template-columns: 92px 1fr; align-items: center; gap: 8px; font-size: 12px; color: rgb(var(--c-text-secondary)); }
.im-field input[type='text'], .im-field input[type='password'] {
  height: 26px;
  padding: 0 8px;
  border: 1px solid rgb(var(--c-border) / 0.14);
  border-radius: 6px;
  background: rgb(var(--c-bg-base));
  color: rgb(var(--c-text-primary));
  font-size: 12px;
  outline: none;
  width: 100%;
  box-sizing: border-box;
}
.im-field input:focus { border-color: rgb(var(--c-primary)); }
.im-field input[type='checkbox'] { justify-self: start; }

/* 窄栏适配 */
@container (max-width: 320px) {
  .im-tab { padding: 0 6px; font-size: 11px; }
}
